public sealed class ReciprocalRankFusionEngine
{
    // Standard constant k=60 prevents high-ranking outliers from dominating
    private const double RankConstant = 60.0;

    public static IReadOnlyList<FusedSearchResult> Fuse(
        IReadOnlyList<SearchResultItem> vectorResults,
        IReadOnlyList<SearchResultItem> lexicalResults,
        int topK = 10)
    {
        var fusedScores = new Dictionary<Guid, (SearchResultItem Item, double Score)>();

        // 1. Process Vector Search Rankings
        for (int rank = 0; rank < vectorResults.Count; rank++)
        {
            var item = vectorResults[rank];
            double contribution = 1.0 / (RankConstant + (rank + 1));

            fusedScores[item.ChunkId] = (item, contribution);
        }

        // 2. Process BM25 Lexical Search Rankings
        for (int rank = 0; rank < lexicalResults.Count; rank++)
        {
            var item = lexicalResults[rank];
            double contribution = 1.0 / (RankConstant + (rank + 1));

            if (fusedScores.TryGetValue(item.ChunkId, out var existing))
            {
                fusedScores[item.ChunkId] = (existing.Item, existing.Score + contribution);
            }
            else
            {
                fusedScores[item.ChunkId] = (item, contribution);
            }
        }

        // 3. Sort descending by combined RRF score
        return fusedScores.Values
            .OrderByDescending(x => x.Score)
            .Take(topK)
            .Select(x => new FusedSearchResult(x.Item.ChunkId, x.Item.DocumentTitle, x.Item.Content, x.Score))
            .ToList();
    }
}

public readonly record struct SearchResultItem(Guid ChunkId, string DocumentTitle, string Content, float OriginalScore);
public readonly record struct FusedSearchResult(Guid ChunkId, string DocumentTitle, string Content, double RrfScore);
